import { Group, Mesh, BoxGeometry, PlaneGeometry, Color, PointLight, DoubleSide } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, smoothstep, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'journal-card-3';

  const CARD_W = 2.0;
  const CARD_H = 1.25;
  const CARD_T = 0.06;

  // ---- contact shadow (grounded object) ----
  const shadowGeo = new PlaneGeometry(CARD_W * 1.35, CARD_H * 1.35);
  const distNode = length(uv().sub(vec2(0.5, 0.5)));
  const shadowAlpha = smoothstep(0.5, 0.0, distNode).mul(0.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });
  shadowMat.opacityNode = shadowAlpha;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -CARD_H * 0.62, -0.02);
  root.add(shadowMesh);

  // ---- accent edge frame (revealed on hover/focus) ----
  const edgeGeo = new PlaneGeometry(CARD_W + 0.09, CARD_H + 0.09);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.0,
    side: DoubleSide,
  });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, 0, -0.02);
  root.add(edgeMesh);

  // ---- machined ink frame body (extruded box, bevel-ish via layered box) ----
  const frameGeo = new BoxGeometry(CARD_W + 0.05, CARD_H + 0.05, CARD_T * 0.7);
  const frameMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.5,
  });
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.set(0, 0, -CARD_T * 0.5);
  root.add(frameMesh);

  // ---- image card face (extruded box, front face = image) ----
  const frontMat = new MeshStandardNodeMaterial({
    color: new Color('#ffffff'),
    roughness: 0.6,
    metalness: 0.25,
  });
  const sideMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.55,
    metalness: 0.5,
  });
  const backMat = sideMat;

  const cardGeo = new BoxGeometry(CARD_W, CARD_H, CARD_T);
  // Box face order: px, nx, py, ny, pz(front), nz(back)
  const cardMesh = new Mesh(cardGeo, [
    sideMat,
    sideMat,
    sideMat,
    sideMat,
    frontMat,
    backMat,
  ]);
  cardMesh.position.set(0, 0, CARD_T * 0.6);
  root.add(cardMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    frontMat.map = tex;
    frontMat.needsUpdate = true;
  }).catch(() => {});

  // ---- rim/accent light (node-local, product-shot style) ----
  const rimLight = new PointLight(new Color(colors.accent), 0.9, 6, 2);
  rimLight.position.set(-1.2, 0.6, 1.4);
  root.add(rimLight);

  // ---- stock badge (data binding target: trpc.inventory.status.inStock) ----
  const badgeGroup = new Group();
  badgeGroup.position.set(CARD_W * 0.5 - 0.35, CARD_H * 0.5 - 0.16, CARD_T * 0.6 + 0.02);
  const badgeGeo = new PlaneGeometry(0.62, 0.2);
  const badgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.92,
  });
  const badgeMesh = new Mesh(badgeGeo, badgeMat);
  badgeGroup.add(badgeMesh);

  const badgeText = ctx.fontAtlas.createText('IN STOCK', {
    fontSize: 22,
    color: colors.paper,
    align: 'center',
  });
  badgeText.position.set(0, 0, 0.01);
  badgeGroup.add(badgeText);
  root.add(badgeGroup);

  let currentBadgeText = badgeText;
  function setInStock(inStock) {
    badgeGroup.remove(currentBadgeText);
    const label = inStock ? 'IN STOCK' : 'SOLD OUT';
    const nextColor = inStock ? colors.accent : colors.ink;
    badgeMat.color = new Color(nextColor);
    currentBadgeText = ctx.fontAtlas.createText(label, {
      fontSize: 22,
      color: colors.paper,
      align: 'center',
    });
    currentBadgeText.position.set(0, 0, 0.01);
    badgeGroup.add(currentBadgeText);
  }

  // ---- caption label under card ----
  const captionText = ctx.fontAtlas.createText('JOURNAL', {
    fontSize: 16,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1.4,
  });
  captionText.position.set(-CARD_W * 0.5 + 0.06, -CARD_H * 0.5 - 0.16, 0);
  root.add(captionText);

  // ---- motion state ----
  const baseY = 0;
  const baseZ = CARD_T * 0.6;
  root.scale.set(1, 1, 1);

  let hoverTl = null;
  let pressTl = null;

  function killTweens() {
    if (hoverTl) { hoverTl.kill(); hoverTl = null; }
    if (pressTl) { pressTl.kill(); pressTl = null; }
  }

  const handlers = {
    pointerenter: () => {
      killTweens();
      hoverTl = gsap.timeline();
      hoverTl.to(root.position, { y: '+=0.15', duration: 0.7, ease: 'power3.out' }, 0);
      hoverTl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' }, 0);
      hoverTl.to(edgeMat, { opacity: 0.85, duration: 0.3, ease: 'power2.out' }, 0);
    },
    pointerleave: () => {
      killTweens();
      hoverTl = gsap.timeline();
      hoverTl.to(root.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
      hoverTl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
      hoverTl.to(edgeMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    },
    pointerdown: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    },
    pointerup: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.2, ease: 'power2.out' });
    },
    click: () => {
      ctx.emit('hub-journal.select', { id: 'hub-journal-card-2' });
    },
  };

  root.userData.handlers = handlers;
  root.userData.setInStock = setInStock;

  root.userData.cleanup = () => {
    killTweens();
    shadowGeo.dispose();
    shadowMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    cardGeo.dispose();
    frontMat.dispose();
    sideMat.dispose();
    badgeGeo.dispose();
    badgeMat.dispose();
    if (frontMat.map) frontMat.map.dispose();
  };

  return root;
}
